class Solution {
public:
    int longestWPI(vector<int>& hours) {
        int score = 0;
        int max_len = 0;
        unordered_map<int, int> seen;
        for (int i = 0; i < (int)hours.size(); ++i) {
            score += (hours[i] > 8 ? 1 : -1);
            if (score > 0) {
                max_len = i + 1;
            } else {
                if (!seen.count(score)) {
                    seen[score] = i;
                }
                if (seen.count(score - 1)) {
                    max_len = max(max_len, i - seen[score - 1]);
                }
            }
        }
        return max_len;
    }
};

import java.util.*;

class Solution {
    public int longestWPI(int[] hours) {
        int score = 0;
        int maxLen = 0;
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < hours.length; i++) {
            score += (hours[i] > 8 ? 1 : -1);
            if (score > 0) {
                maxLen = i + 1;
            } else {
                if (!seen.containsKey(score)) {
                    seen.put(score, i);
                }
                if (seen.containsKey(score - 1)) {
                    maxLen = Math.max(maxLen, i - seen.get(score - 1));
                }
            }
        }
        return maxLen;
    }
}

var longestWPI = function(hours) {
    let score = 0;
    let maxLen = 0;
    const seen = new Map();
    for (let i = 0; i < hours.length; i++) {
        score += hours[i] > 8 ? 1 : -1;
        if (score > 0) {
            maxLen = i + 1;
        } else {
            if (!seen.has(score)) {
                seen.set(score, i);
            }
            if (seen.has(score - 1)) {
                maxLen = Math.max(maxLen, i - seen.get(score - 1));
            }
        }
    }
    return maxLen;
};
